16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
20	import org.springframework.samples.petclinic.rest.validation.LuhnCheckDigit;
21	import org.springframework.samples.petclinic.rest.validation.TelephoneFormatter;
22	
23	import jakarta.persistence.*;
24	import jakarta.validation.constraints.NotEmpty;
25	import jakarta.validation.constraints.Pattern;
26	
27	import java.time.LocalDate;
28	import java.time.temporal.ChronoUnit;
29	import java.util.*;
30	
31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "title")
43	    private String title;
44	
45	    @Column(name = "address")
46	    @NotEmpty
47	    private String address;
48	
49	    @Column(name = "address_line1")
50	    private String addressLine1;
51	
52	    @Column(name = "address_line2")
53	    private String addressLine2;
54	
55	    @Column(name = "city")
56	    @NotEmpty
57	    private String city;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    private String email;
66	
67	    @Column(name = "postcode")
68	    private String postcode;
69	
70	    @Column(name = "registration_date")
71	    private LocalDate registrationDate;
72	
73	    @Column(name = "birth_date")
74	    private LocalDate birthDate;
75	
76	    @Column(name = "customer_code")
77	    private String customerCode;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "membership_number")
89	    private String membershipNumber;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
95	    private Set<Pet> pets;
96	
97	    /**
98	     * Default the registration date to the server's current date when none was
99	     * supplied, then roll the effective date forward onto a business day so a
100	     * weekend registration date always lands on the following Monday. Runs only
101	     * on insert.
102	     */
103	    @PrePersist
104	    private void defaultRegistrationDate() {
105	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
106	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
107	    }
108	
109	    public String getTitle() {
110	        return this.title;
111	    }
112	
113	    public void setTitle(String title) {
114	        this.title = title;
115	    }
116	
117	    public String getAddress() {
118	        return this.address;
119	    }
120	
121	    public void setAddress(String address) {
122	        this.address = address;
123	    }
124	
125	    public String getAddressLine1() {
126	        return this.addressLine1;
127	    }
128	
129	    public void setAddressLine1(String addressLine1) {
130	        this.addressLine1 = addressLine1;
131	    }
132	
133	    public String getAddressLine2() {
134	        return this.addressLine2;
135	    }
136	
137	    public void setAddressLine2(String addressLine2) {
138	        this.addressLine2 = addressLine2;
139	    }
140	
141	    public String getCity() {
142	        return this.city;
143	    }
144	
145	    public void setCity(String city) {
146	        this.city = city;
147	    }
148	
149	    public String getTelephone() {
150	        return this.telephone;
151	    }
152	
153	    public void setTelephone(String telephone) {
154	        this.telephone = telephone;
155	    }
156	
157	    public String getEmail() {
158	        return this.email;
159	    }
160	
161	    public void setEmail(String email) {
162	        this.email = email;
163	    }
164	
165	    public String getPostcode() {
166	        return this.postcode;
167	    }
168	
169	    public void setPostcode(String postcode) {
170	        this.postcode = postcode;
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
176	
177	    public void setRegistrationDate(LocalDate registrationDate) {
178	        this.registrationDate = registrationDate;
179	    }
180	
181	    public LocalDate getBirthDate() {
182	        return this.birthDate;
183	    }
184	
185	    public void setBirthDate(LocalDate birthDate) {
186	        this.birthDate = birthDate;
187	    }
188	
189	    public String getCustomerCode() {
190	        return this.customerCode;
191	    }
192	
193	    public void setCustomerCode(String customerCode) {
194	        this.customerCode = customerCode;
195	    }
196	
197	    public String getHouseholdId() {
198	        return this.householdId;
199	    }
200	
201	    public void setHouseholdId(String householdId) {
202	        this.householdId = householdId;
203	    }
204	
205	    public Integer getNamesakeCount() {
206	        return this.namesakeCount;
207	    }
208	
209	    public void setNamesakeCount(Integer namesakeCount) {
210	        this.namesakeCount = namesakeCount;
211	    }
212	
213	    public Integer getHouseholdSize() {
214	        return this.householdSize;
215	    }
216	
217	    public void setHouseholdSize(Integer householdSize) {
218	        this.householdSize = householdSize;
219	    }
220	
221	    public String getMembershipNumber() {
222	        return this.membershipNumber;
223	    }
224	
225	    public void setMembershipNumber(String membershipNumber) {
226	        this.membershipNumber = membershipNumber;
227	    }
228	
229	    public Integer getPossibleDuplicateOf() {
230	        return this.possibleDuplicateOf;
231	    }
232	
233	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
234	        this.possibleDuplicateOf = possibleDuplicateOf;
235	    }
236	
237	    /**
238	     * Return whether this owner is a possible duplicate: true when it was created while an existing
239	     * owner already shared its last name and postcode under a different telephone, i.e. when a
240	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
241	     */
242	    @Transient
243	    public boolean getPossibleDuplicate() {
244	        return this.possibleDuplicateOf != null;
245	    }
246	
247	    /**
248	     * Return this owner's name formatted as {@code LastName, FirstName}.
249	     */
250	    @Transient
251	    public String getDisplayName() {
252	        return this.getLastName() + ", " + this.getFirstName();
253	    }
254	
255	    /**
256	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
257	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
258	     */
259	    @Transient
260	    public String getSalutation() {
261	        if (this.title == null || this.title.isBlank()) {
262	            return this.getLastName();
263	        }
264	        return this.title + " " + this.getLastName();
265	    }
266	
267	    /**
268	     * Return this owner's telephone formatted for human display: the country code, a space, then
269	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
270	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
271	     */
272	    @Transient
273	    public String getTelephoneDisplay() {
274	        return TelephoneFormatter.format(this.telephone);
275	    }
276	
277	    /**
278	     * Return this owner's identity key: the derived value formed as
279	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
280	     * contributes an empty segment). Members of the same household share a household id but, having
281	     * different telephones, still have distinct identity keys. The telephone and email are expected
282	     * to already be in their normalized storage form.
283	     */
284	    @Transient
285	    public String getIdentityKey() {
286	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
287	    }
288	
289	    private static String orEmpty(String value) {
290	        return value == null ? "" : value;
291	    }
292	
293	    /**
294	     * Return this owner's locality: the REGION segment of the owner's
295	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
296	     * When no customer code has been assigned yet the region is resolved directly from the
297	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
298	     */
299	    @Transient
300	    public String getLocality() {
301	        if (this.customerCode != null && !this.customerCode.isBlank()) {
302	            return CustomerCodeGenerator.regionOf(this.customerCode);
303	        }
304	        return RegionResolver.regionFor(this.postcode, this.city);
305	    }
306	
307	    /**
308	     * Return this owner's timezone: the IANA name mapped from the owner's
309	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
310	     * region has no known timezone.
311	     */
312	    @Transient
313	    public String getTimezone() {
314	        return RegionTimezones.timezoneOf(getLocality());
315	    }
316	
317	    /**
318	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
319	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
320	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
321	     * for long tenure ({@link #getTenureDays() tenure} of more than 365 days).
322	     */
323	    @Transient
324	    public int getMembershipPoints() {
325	        boolean hasEmail = this.email != null && !this.email.isEmpty();
326	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
327	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
328	        boolean longTenure = getTenureDays() > 365;
329	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
330	    }
331	
332	    /**
333	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
334	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
335	     */
336	    @Transient
337	    public int getMembershipLevel() {
338	        return MembershipPoints.levelFor(getMembershipPoints());
339	    }
340	
341	    /**
342	     * Return this owner's tenure in whole days: the number of days elapsed from the
343	     * {@link #getRegistrationDate() registration date} to today. A newly created owner
344	     * whose registration date is today has zero tenure. Zero when no registration date
345	     * is known.
346	     */
347	    @Transient
348	    public long getTenureDays() {
349	        if (this.registrationDate == null) {
350	            return 0;
351	        }
352	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
353	    }
354	
355	    /**
356	     * Return this owner's check digit: the single Luhn check digit computed over the
357	     * digits of the {@link #getCustomerCode() customer code}.
358	     */
359	    @Transient
360	    public int getCheckDigit() {
361	        return LuhnCheckDigit.of(this.customerCode);
362	    }
363	
364	    /**
365	     * Return this owner's preferred contact channel: {@code EMAIL} when an
366	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
367	     */
368	    @Transient
369	    public String getContactPreference() {
370	        boolean hasEmail = this.email != null && !this.email.isEmpty();
371	        return hasEmail ? "EMAIL" : "PHONE";
372	    }
373	
374	    /**
375	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
376	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
377	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
378	     */
379	    @Transient
380	    public String getAgeBand() {
381	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
382	        return ageBand == null ? null : ageBand.name();
383	    }
384	
385	    protected Set<Pet> getPetsInternal() {
386	        if (this.pets == null) {
387	            this.pets = new HashSet<>();
388	        }
389	        return this.pets;
390	    }
391	
392	    protected void setPetsInternal(Set<Pet> pets) {
393	        this.pets = pets;
394	    }
395	
396	    public List<Pet> getPets() {
397	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
398	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
399	        return Collections.unmodifiableList(sortedPets);
400	    }
401	
402	    public void setPets(List<Pet> pets) {
403	        this.pets = new HashSet<>(pets);
404	    }
405	
406	    public void addPet(Pet pet) {
407	        getPetsInternal().add(pet);
408	        pet.setOwner(this);
409	    }
410	
411	    /**
412	     * Return the Pet with the given name, or null if none found for this Owner.
413	     *
414	     * @param name to test
415	     * @return true if pet name is already in use
416	     */
417	    public Pet getPet(String name) {
418	        return getPet(name, false);
419	    }
420	
421	    /**
422	     * Return the Pet with the given name, or null if none found for this Owner.
423	     *
424	     * @param name to test
425	     * @return true if pet name is already in use
426	     */
427	    public Pet getPet(String name, boolean ignoreNew) {
428	        name = name.toLowerCase();
429	        for (Pet pet : getPetsInternal()) {
430	            if (!ignoreNew || !pet.isNew()) {
431	                String compName = pet.getName();
432	                compName = compName.toLowerCase();
433	                if (compName.equals(name)) {
434	                    return pet;
435	                }
436	            }
437	        }
438	        return null;
439	    }
440	
441	    public Pet getPet(Integer petId) {
442	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
443	    }
444	
445	    @Override
446	    public String toString() {
447	        return new ToStringCreator(this)
448	
449	            .append("id", this.getId())
450	            .append("new", this.isNew())
451	            .append("lastName", this.getLastName())
452	            .append("firstName", this.getFirstName())
453	            .append("address", this.address)
454	            .append("city", this.city)
455	            .append("telephone", this.telephone)
456	            .append("email", this.email)
457	            .toString();
458	    }
459	}
