46	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
47	import org.springframework.samples.petclinic.rest.validation.DisposableEmailDomainValidator;
48	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
49	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
50	import org.springframework.samples.petclinic.rest.validation.HouseholdKey;
51	import org.springframework.samples.petclinic.rest.validation.HouseholdSizeCounter;
52	import org.springframework.samples.petclinic.rest.validation.MembershipNumberGenerator;
53	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
54	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
55	import org.springframework.samples.petclinic.rest.validation.PossibleDuplicateOwnerDetector;
56	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
57	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
58	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
59	import org.springframework.samples.petclinic.service.ClinicService;
60	import org.springframework.security.access.prepost.PreAuthorize;
61	import org.springframework.web.bind.annotation.CrossOrigin;
62	import org.springframework.web.bind.annotation.RequestMapping;
63	import org.springframework.web.bind.annotation.RestController;
64	import org.springframework.web.util.UriComponentsBuilder;
65	
66	import jakarta.transaction.Transactional;
67	
68	/**
69	 * @author Vitaliy Fedoriv
70	 */
71	
72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final HouseholdDuplicateValidator householdDuplicateValidator;
86	
87	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
88	
89	    private final NamesakeCounter namesakeCounter;
90	
91	    private final HouseholdSizeCounter householdSizeCounter;
92	
93	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
94	
95	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
96	
97	    private final OwnerAuditLogger ownerAuditLogger;
98	
99	    private final CustomerCodeDeduplicator customerCodeDeduplicator;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 HouseholdDuplicateValidator householdDuplicateValidator,
106	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
107	                                 NamesakeCounter namesakeCounter,
108	                                 HouseholdSizeCounter householdSizeCounter,
109	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
110	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
111	                                 OwnerAuditLogger ownerAuditLogger,
112	                                 CustomerCodeDeduplicator customerCodeDeduplicator) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.householdDuplicateValidator = householdDuplicateValidator;
118	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
119	        this.namesakeCounter = namesakeCounter;
120	        this.householdSizeCounter = householdSizeCounter;
121	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
122	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
123	        this.ownerAuditLogger = ownerAuditLogger;
124	        this.customerCodeDeduplicator = customerCodeDeduplicator;
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
130	        Collection<Owner> owners;
131	        if (lastName != null) {
132	            owners = this.clinicService.findOwnerByLastName(lastName);
133	        } else {
134	            owners = this.clinicService.findAllOwners();
135	        }
136	        if (owners.isEmpty()) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
155	        normalizeAddress(ownerFieldsDto);
156	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
160	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
161	        DisposableEmailDomainValidator.validate(owner.getEmail());
162	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
163	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
164	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
165	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
166	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
167	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
168	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
169	            // An owner sharing a household (same last name and postcode) is otherwise a household
170	            // duplicate. A declared member bypasses this block, and is not a suspected duplicate.
171	            this.householdDuplicateValidator.rejectIfHouseholdExists(owner);
172	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
173	                .ifPresent(owner::setPossibleDuplicateOf);
174	        }
175	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
176	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
177	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
178	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
179	        String customerCode = CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
180	        owner.setCustomerCode(this.customerCodeDeduplicator.deduplicate(customerCode));
181	        this.clinicService.saveOwner(owner);
182	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
183	        this.ownerAuditLogger.logCreated(owner);
184	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    /**
191	     * Normalize the submitted address fields and resolve the effective {@code address}. The
192	     * structured lines are normalized in place; when a non-blank {@code addressLine1} is supplied it
193	     * takes precedence and {@code address} is composed from the normalized lines, otherwise the flat
194	     * {@code address} input is normalized and kept for backward compatibility.
195	     */
196	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
197	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
198	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
199	        ownerFieldsDto.setAddressLine1(line1);
200	        ownerFieldsDto.setAddressLine2(line2);
201	        if (line1 != null && !line1.isBlank()) {
202	            ownerFieldsDto.setAddress(AddressNormalizer.compose(line1, line2));
203	        } else {
204	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
205	        }
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
211	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
212	        if (currentOwner == null) {
213	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	        }
215	        currentOwner.setAddress(ownerFieldsDto.getAddress());
216	        currentOwner.setCity(ownerFieldsDto.getCity());
217	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
218	        currentOwner.setLastName(ownerFieldsDto.getLastName());
219	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
220	        this.clinicService.saveOwner(currentOwner);
221	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Transactional
226	    @Override
227	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        this.clinicService.deleteOwner(owner);
233	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner == null) {
241	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	        }
243	        HttpHeaders headers = new HttpHeaders();
244	        Pet pet = petMapper.toPet(petFieldsDto);
245	        owner.setId(ownerId);
246	        pet.setOwner(owner);
247	        pet.getType().setName(null);
248	        this.clinicService.savePet(pet);
249	        PetDto petDto = petMapper.toPetDto(pet);
250	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
251	            .buildAndExpand(pet.getId()).toUri());
252	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
258	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
259	        if (currentOwner != null) {
260	            Pet currentPet = this.clinicService.findPetById(petId);
261	            if (currentPet != null) {
262	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
263	                currentPet.setName(petFieldsDto.getName());
264	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
265	                this.clinicService.savePet(currentPet);
266	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
267	            }
268	        }
269	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
275	        HttpHeaders headers = new HttpHeaders();
276	        Visit visit = visitMapper.toVisit(visitFieldsDto);
277	        Pet pet = new Pet();
278	        pet.setId(petId);
279	        visit.setPet(pet);
280	        this.clinicService.saveVisit(visit);
281	        VisitDto visitDto = visitMapper.toVisitDto(visit);
282	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
283	            .buildAndExpand(visit.getId()).toUri());
284	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
285	    }
286	
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
291	        Owner owner = this.clinicService.findOwnerById(ownerId);
292	        if (owner != null) {
293	            Pet pet = owner.getPet(petId);
294	            if (pet != null) {
295	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
296	            }
297	        }
298	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
299	    }
300	}
