26	
27	/**
28	 * Detects "possible duplicate" owners: a new owner that is not a household duplicate (see
29	 * {@link HouseholdDuplicateValidator}) but still shares an existing owner's last name (compared
30	 * case-insensitively) and postcode under a <em>different</em> telephone. The comparison is done in
31	 * memory because the stored last names are not kept in a normalized form, for the same reason as the
32	 * name matching in {@link NamesakeCounter}.
33	 */
34	@Component
35	public class PossibleDuplicateOwnerDetector {
36	
37	    private final ClinicService clinicService;
38	
39	    public PossibleDuplicateOwnerDetector(ClinicService clinicService) {
40	        this.clinicService = clinicService;
41	    }
42	
43	    /**
44	     * Finds the existing owner the given (not-yet-saved) owner is a possible duplicate of: the
45	     * earliest owner sharing its last name (case-insensitively) and postcode but registered under a
46	     * different telephone. The owner's telephone is expected to already be in its normalized form.
47	     *
48	     * @param owner the owner being created
49	     * @return the id of the earliest matching owner, or empty when the owner is not a possible
50	     *         duplicate of any existing owner
51	     */
52	    public Optional<Integer> findPossibleDuplicateOf(Owner owner) {
53	        if (owner.getPostcode() == null) {
54	            return Optional.empty();
55	        }
56	        return this.clinicService.findAllOwners().stream()
57	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName()))
58	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
59	            .filter(existing -> !Objects.equals(existing.getTelephone(), owner.getTelephone()))
60	            .min(Comparator.comparing(Owner::getId))
61	            .map(Owner::getId);
62	    }
63	
64	    private static boolean equalsIgnoreCase(String a, String b) {
65	        return a != null && a.equalsIgnoreCase(b);
66	    }
67	}
